select jsonb_build_object('project','xtvueqciogzkyjkkqxcx','captured_at',now(),'tables',jsonb_build_object('poc_user_directory', (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]') from public.poc_user_directory t),'poc_config', (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]') from public.poc_config t),'poc_candidates', (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]') from public.poc_candidates t),'poc_approvals', (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]') from public.poc_approvals t),'poc_publications', (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]') from public.poc_publications t),'poc_events', (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]') from public.poc_events t),'poc_private_notices', (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]') from public.poc_private_notices t),'poc_adjustment_tokens', (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]') from public.poc_adjustment_tokens t)),
'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'security_definer',p.prosecdef,'acl',p.proacl) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'poc_%'),
'columns',(select jsonb_agg(to_jsonb(c) order by c.table_name,c.ordinal_position) from information_schema.columns c where table_schema='public' and table_name like 'poc_%'),
'constraints',(select jsonb_agg(jsonb_build_object('table',r.relname,'name',c.conname,'definition',pg_get_constraintdef(c.oid)) order by r.relname,c.conname) from pg_constraint c join pg_class r on r.oid=c.conrelid join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relname like 'poc_%'),
'indexes',(select jsonb_agg(to_jsonb(i) order by tablename,indexname) from pg_indexes i where schemaname='public' and tablename like 'poc_%'),
'grants',(select jsonb_agg(to_jsonb(g) order by table_name,grantee,privilege_type) from information_schema.role_table_grants g where table_schema='public' and table_name like 'poc_%'),
'rls',(select jsonb_agg(jsonb_build_object('table',relname,'enabled',relrowsecurity,'forced',relforcerowsecurity) order by relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and relname like 'poc_%' and relkind='r'),
'policies',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from pg_policies p where schemaname='public' and tablename like 'poc_%'),
'evidence_sequence',(select last_value from public.poc_events_id_seq)
) as backup;